`ifndef GUARD_SDIO_FULL_BOOT_TEST_SV
`define GUARD_SDIO_FULL_BOOT_TEST_SV

`include "sdio_base_test.sv"

// vplan MEGASOC-BOOT-006 (full boot: ROM -> QSPI -> DRAM+SDIO -> SD image ->
// DRAM). Preloads the SD card model with the boot image that the embedded
// loader (megasoc_tech/software/src/full_boot_sd_dram_tests) copies into DRAM
// and runs. Pass/fail is decided by the embedded software (TEST_PASS/
// TEST_FAIL); this test only puts the image on the card.
//
// Image file: one byte per line ($readmemh style, '//' comments allowed),
// generated by sd_image/gen_sd_boot_image.py. Default path is relative to the
// simulation run directory (simulate/<sim dir>/<TESTNAME>/); override with
// +SD_BOOT_IMAGE=<file>.
//
// Card addressing (see sdio_vip_tc3_test.sv for how this was found): the
// card memory is block-addressed, one 4096-bit word per 512-byte sector, and
// every CMD0 from the host clears it, so the image is re-poked after each
// CMD0.

localparam int unsigned FULL_BOOT_SECTOR_BYTES = 512;
// Must match SD_BOOT_IMAGE_SECTOR in full_boot_sd_dram_tests.c
localparam int unsigned FULL_BOOT_IMAGE_SECTOR = 'h3000;
// Write-path check, must match full_boot_sd_dram_tests.c: the firmware writes
// sector 'h3100 alone (PIO) and 'h3101-'h3102 together (DMA); byte k of the
// 3-sector pattern is (k * 7 + 'h11) & 'hff.
localparam int unsigned FULL_BOOT_WR_SECTOR  = 'h3100;
localparam int unsigned FULL_BOOT_WR_SECTORS = 3;
localparam string       FULL_BOOT_IMAGE_DEFAULT =
  "../../../megasoc_tech/software/src/full_boot_sd_dram_tests/sd_image/sd_boot_image.hex";

class sdio_full_boot_image;

  byte unsigned bytes[$];

  function int unsigned num_sectors();
    return bytes.size() / FULL_BOOT_SECTOR_BYTES;
  endfunction : num_sectors

  // Returns an empty string on success, else the reason for failure
  function string load(string path);
    int    fd;
    string line;
    int    b;

    bytes.delete();
    fd = $fopen(path, "r");
    if (fd == 0)
      return $sformatf("cannot open SD boot image '%s'", path);
    while ($fgets(line, fd) > 0) begin
      if (line.len() < 2 || line.substr(0, 1) == "//")
        continue;
      if ($sscanf(line, "%h", b) == 1)
        bytes.push_back(b[7:0]);
    end
    $fclose(fd);

    if (bytes.size() == 0 || bytes.size() % FULL_BOOT_SECTOR_BYTES != 0)
      return $sformatf("SD boot image '%s' is %0d bytes, not a whole number of sectors",
                       path, bytes.size());
    // Header word 0 is the "MSBI" magic, little-endian
    if ({bytes[3], bytes[2], bytes[1], bytes[0]} != 32'h4942534D)
      return $sformatf("SD boot image '%s' has no MSBI header", path);
    return "";
  endfunction : load

  function svt_mem_data_t sector_word(int unsigned s);
    svt_mem_data_t word = '0;
    for (int unsigned i = 0; i < FULL_BOOT_SECTOR_BYTES; i++)
      word[i*8 +: 8] = bytes[s*FULL_BOOT_SECTOR_BYTES + i];
    return word;
  endfunction : sector_word

  function void poke_all(svt_mem_backdoor mem_back_door);
    for (int unsigned s = 0; s < num_sectors(); s++)
      mem_back_door.poke(FULL_BOOT_IMAGE_SECTOR + s, sector_word(s));
  endfunction : poke_all

  function bit peek_check(svt_mem_backdoor mem_back_door);
    svt_mem_data_t rd_word;
    for (int unsigned s = 0; s < num_sectors(); s++) begin
      void'(mem_back_door.peek(FULL_BOOT_IMAGE_SECTOR + s, rd_word));
      if (rd_word != sector_word(s))
        return 0;
    end
    return 1;
  endfunction : peek_check

endclass : sdio_full_boot_image

class full_boot_cmd0_repoke_subscriber extends uvm_subscriber #(svt_emmc_card_transaction);

  svt_mem_backdoor     mem_back_door;
  sdio_full_boot_image image;

  `uvm_component_utils(full_boot_cmd0_repoke_subscriber)

  function new(string name = "full_boot_cmd0_repoke_subscriber", uvm_component parent = null);
    super.new(name, parent);
  endfunction : new

  function void write(svt_emmc_card_transaction t);
    if (t.cmd_type == svt_emmc_types::CMD0) begin
      image.poke_all(mem_back_door);
      `uvm_info("write", $sformatf(
        "CMD0 observed -- re-poked SD boot image (%0d sectors at 0x%0h).",
        image.num_sectors(), FULL_BOOT_IMAGE_SECTOR), UVM_LOW)
    end
  endfunction : write

endclass : full_boot_cmd0_repoke_subscriber

class sdio_full_boot_test extends sdio_base_test;

  full_boot_cmd0_repoke_subscriber cmd0_repoke;
  sdio_full_boot_image             image;

  `uvm_component_utils(sdio_full_boot_test)

  function new(string name = "sdio_full_boot_test", uvm_component parent = null);
    super.new(name, parent);
  endfunction : new

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    image = new();
    cmd0_repoke = full_boot_cmd0_repoke_subscriber::type_id::create("cmd0_repoke", this);
    cmd0_repoke.image = image;
  endfunction : build_phase

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    sd_env.card_agent.card_mon.rx_card_xact_observed_port.connect(cmd0_repoke.analysis_export);
  endfunction : connect_phase

  function void start_of_simulation_phase(uvm_phase phase);
    svt_mem_backdoor mem_back_door;
    string           path;
    string           err;

    super.start_of_simulation_phase(phase);

    if (!$value$plusargs("SD_BOOT_IMAGE=%s", path))
      path = FULL_BOOT_IMAGE_DEFAULT;
    err = image.load(path);
    if (err != "")
      `uvm_fatal("start_of_simulation_phase", err)

    mem_back_door = sd_env.card_agent.mem_sequencer.get_backdoor();
    if (mem_back_door == null)
      `uvm_fatal("start_of_simulation_phase", "Could not obtain card memory backdoor handle.")
    cmd0_repoke.mem_back_door = mem_back_door;

    image.poke_all(mem_back_door);
    if (!image.peek_check(mem_back_door))
      `uvm_fatal("start_of_simulation_phase", "SD boot image peek-after-poke mismatch -- aborting before the embedded software runs.")

    `uvm_info("start_of_simulation_phase", $sformatf(
      "SD boot image '%s' preloaded: %0d sectors at 0x%0h, peek check passed.",
      path, image.num_sectors(), FULL_BOOT_IMAGE_SECTOR), UVM_LOW)
  endfunction : start_of_simulation_phase

  // Run the card check as soon as the embedded software finishes: on
  // INC_LPDDR4 builds sdio_base_test::run_phase ends the simulation with
  // uvm_root::die(), which skips check_phase. The firmware's sdio_write()
  // calls complete before TEST_PASS()/TEST_FAIL(), so the card is final here.
  task run_phase(uvm_phase phase);
    fork
      super.run_phase(phase);
    join_none
    wait (sim_done_vif.done == 1'b1);
    check_card_pattern();
  endtask : run_phase

  // Checks the byte order the DUT wrote to the card, against the card memory
  // itself (a write-then-read round trip through the DUT cannot see it).
  function void check_card_pattern();
    svt_mem_backdoor mem_back_door;
    svt_mem_data_t   rd_word;
    int unsigned     bad;

    mem_back_door = sd_env.card_agent.mem_sequencer.get_backdoor();
    for (int unsigned s = 0; s < FULL_BOOT_WR_SECTORS; s++) begin
      bad = 0;
      void'(mem_back_door.peek(FULL_BOOT_WR_SECTOR + s, rd_word));
      for (int unsigned i = 0; i < FULL_BOOT_SECTOR_BYTES; i++)
        if (rd_word[i*8 +: 8] != 8'((s*FULL_BOOT_SECTOR_BYTES + i) * 7 + 'h11))
          bad++;
      if (bad == 0)
        `uvm_info("check_phase", $sformatf(
          "Card sector 0x%0h (%s write) holds the expected pattern in byte order.",
          FULL_BOOT_WR_SECTOR + s, (s == 0) ? "PIO" : "DMA"), UVM_LOW)
      else
        `uvm_error("check_phase", $sformatf(
          "Card sector 0x%0h (%s write): %0d of %0d bytes wrong; bytes 0-3 = %02h %02h %02h %02h, expected %02h %02h %02h %02h.",
          FULL_BOOT_WR_SECTOR + s, (s == 0) ? "PIO" : "DMA", bad, FULL_BOOT_SECTOR_BYTES,
          rd_word[7:0], rd_word[15:8], rd_word[23:16], rd_word[31:24],
          8'((s*FULL_BOOT_SECTOR_BYTES) * 7 + 'h11), 8'((s*FULL_BOOT_SECTOR_BYTES + 1) * 7 + 'h11),
          8'((s*FULL_BOOT_SECTOR_BYTES + 2) * 7 + 'h11), 8'((s*FULL_BOOT_SECTOR_BYTES + 3) * 7 + 'h11)))
    end
  endfunction : check_card_pattern

endclass : sdio_full_boot_test

`endif // GUARD_SDIO_FULL_BOOT_TEST_SV
